// VM is the shared utility library, loaded globally via _includes/head-scripts.html (js/**). This page uses VM.discreteMath.barycentricTriples, VM.discreteMath.subTriangleTriples, VM.discreteMath.spernerColor, VM.discreteMath.randomColor, VM.discreteMath.triangulationEdges, VM.discreteMath.pairColor, VM.discreteMath.triangleFillColor, VM.discreteMath.vertexColor.
VM = window.VM
vmTheme = Generators.observe(notify =&gt; VM.plotting.onThemeChange(notify))
chartColors = VM.plotting.colors(vmTheme)
This is my new favorite proof of Sperner’s lemma. In the following app the vertices are slowly morphed to the “cardinal” R, G, B vertices with time while preserving the adjacency relations. Only the rainbow (RGB) triangles are shaded — everything else is left unfilled. Both orientations use the same purple, distinguished by shading: light, ⟋-hatched triangles are oriented counter-clockwise and dark, ⟍-hatched triangles are oriented clockwise. Can you come up with the proof yourself without peeking below? You can try reducing the number of subdivisions to get a sense of what’s going on.
vertices = [
  {x: 1, y: 0},
  {x: 0.5, y: Math.sqrt(3) / 2},
  {x: 0, y: 0},
];
// Colors every vertex red/green/blue at t=0, moves each vertex linearly
// toward its own color's "cardinal" vertex as t goes from 0 to 1, and
// re-derives the (possibly degenerate) sub-triangles at each t.
function createTriangleMorpher(N, vertices, assignColor) {
  const baryCoords = VM.discreteMath.barycentricTriples(N)

  const buildColorMap = () =&gt; {
    const map = new Map()
    for (const [a, b, c] of baryCoords) {
      map.set(`${a},${b},${c}`, assignColor(a, b, c))
    }
    return map
  }

  const interpolatePoints = (t, colorMap) =&gt; {
    const [A, B, C] = vertices
    const vertexMap = { red: C, green: A, blue: B }

    const morphedPoints = []
    for (const [a, b, c] of baryCoords) {
      const sum = a + b + c
      const x0 = (a * A.x + b * B.x + c * C.x) / sum
      const y0 = (a * A.y + b * B.y + c * C.y) / sum

      const color = colorMap.get(`${a},${b},${c}`)
      const target = vertexMap[color]

      morphedPoints.push({
        x: (1 - t) * x0 + t * target.x,
        y: (1 - t) * y0 + t * target.y,
        color,
        barycentricTriple: [a, b, c]
      })
    }

    const morphedMap = new Map()
    for (const p of morphedPoints) morphedMap.set(p.barycentricTriple.join(','), p)
    return { morphedPoints, morphedMap }
  }

  const generateSubTriangles = morphedMap =&gt; {
    const triangles = []
    for (const coordinates of VM.discreteMath.subTriangleTriples(N)) {
      const vertex_colors = []
      for (const c of coordinates) vertex_colors.push(morphedMap.get(c.join(',')).color)
      triangles.push({ coordinates, vertex_colors })
    }
    return triangles
  }

  return {
    baryCoords,
    buildColorMap,
    interpolatePoints,
    generateSubTriangles
  }
}
// simplerAssignColor deliberately violates Sperner's condition: only the
// three outer vertices get a fixed color, every other point (including
// boundary points) is fully random -- used as a "what goes wrong" foil for
// the correctly-colored triangulation (VM.discreteMath.spernerColor) below.
simplerAssignColor = (a, b, c) =&gt; {
  if (a === 0 && b === 0) return 'red'
  if (b === 0 && c === 0) return 'green'
  if (c === 0 && a === 0) return 'blue'
  return VM.discreteMath.randomColor()
}
fillColorGroups = {
  const group1 = new Set(['RGB', 'GBR', 'BRG'])
  const group2 = new Set(['RBG', 'BGR', 'GRB'])
  return { group1, group2 }
}

// Whether an RGB triangle's vertices, read in their own (counterclockwise)
// order, visit the colors in the same cyclic order as the outer triangle
// ('ccw') or the reverse ('cw'). Returns null for a non-rainbow triangle.
triangleOrientation = vertexColors =&gt; {
  const map = { red: 'R', green: 'G', blue: 'B' }
  let key = ''
  for (const c of vertexColors) key += map[c.toLowerCase()] || ''

  if (fillColorGroups.group1.has(key)) return 'ccw'
  if (fillColorGroups.group2.has(key)) return 'cw'
  return null
}
// One color (the same palette purple, accent2, used for rainbow triangles
// on every Sperner's lemma page -- passed in by the caller, which holds the
// current theme's snapshot) for both orientations -- distinguished by
// shading, not hue: counter-clockwise is a light diagonal hatch sloped one
// way, clockwise is a darker, denser hatch sloped the other way. IDs are
// unique per call since this page renders two comparison panels in the
// same document, and SVG pattern references are resolved by document-wide
// id.
function makeOrientationDefs(ccwId, cwId, color) {
  const svgNS = "http://www.w3.org/2000/svg";
  const defs = document.createElementNS(svgNS, "defs");

  function hatch(id, angleDegrees, shadeOpacity) {
    const pattern = document.createElementNS(svgNS, "pattern");
    pattern.setAttribute("id", id);
    pattern.setAttribute("width", "8");
    pattern.setAttribute("height", "8");
    pattern.setAttribute("patternUnits", "userSpaceOnUse");
    pattern.setAttribute("patternTransform", `rotate(${angleDegrees})`);

    const background = document.createElementNS(svgNS, "rect");
    background.setAttribute("width", "8");
    background.setAttribute("height", "8");
    background.setAttribute("fill", color);
    background.setAttribute("fill-opacity", String(shadeOpacity));
    pattern.appendChild(background);

    const stripe = document.createElementNS(svgNS, "line");
    stripe.setAttribute("x1", "0");
    stripe.setAttribute("y1", "0");
    stripe.setAttribute("x2", "0");
    stripe.setAttribute("y2", "8");
    stripe.setAttribute("stroke", color);
    stripe.setAttribute("stroke-width", "3");
    stripe.setAttribute("stroke-opacity", String(Math.min(1, shadeOpacity + 0.35)));
    pattern.appendChild(stripe);

    defs.appendChild(pattern);
  }

  hatch(ccwId, 45, 0.25);   // light shade, ⟋
  hatch(cwId, -45, 0.6);    // dark shade, ⟍

  return defs;
}
// `colors` is the caller's VM.plotting.colors() snapshot (chartColors), so
// a plot cell that passes it re-runs, and repaints, on a theme toggle.
function plotTriangles(triangles, morphedPoints, N, colors) {
  // Edges between differently-colored (morphed) vertices, in the shared
  // amber/teal/purple pair palette used elsewhere for mixed edges.
  const mixedEdges = [];
  for (const { a, b } of VM.discreteMath.triangulationEdges(N)) {
    const pa = morphedPoints.morphedMap.get(a.join(','));
    const pb = morphedPoints.morphedMap.get(b.join(','));
    const color = VM.discreteMath.pairColor(pa.color, pb.color);
    if (!color) continue;
    mixedEdges.push({ x1: pa.x, y1: pa.y, x2: pb.x, y2: pb.y, color });
  }

  const uid = Math.random().toString(36).slice(2);
  const ccwId = `hatch-ccw-${uid}`;
  const cwId = `hatch-cw-${uid}`;

  const fillFor = tri =&gt; {
    const orientation = triangleOrientation(tri.vertex_colors);
    if (orientation === 'ccw') return `url(#${ccwId})`;
    if (orientation === 'cw') return `url(#${cwId})`;
    // Not a rainbow triangle: no fill, so the rainbow triangles stay the focus.
    return VM.discreteMath.triangleFillColor(tri.vertex_colors);
  };

  const features = [];
  for (const tri of triangles) {
    const ring = [];
    for (const c of tri.coordinates) {
      const p = morphedPoints.morphedMap.get(c.join(','));
      ring.push([p.x, p.y]);
    }
    ring.push(ring[0]);
    features.push({
      type: "Feature",
      geometry: { type: "Polygon", coordinates: [ring] },
      properties: { fillColor: fillFor(tri) }
    });
  }

  // A diagram, not a graph: no axes, and a height chosen so the unit-wide
  // equilateral triangle is drawn to scale (Plot stretches y to fill
  // whatever height it is given otherwise).
  const width = 800;
  const margin = 20;
  const height = (width - 2 * margin) * Math.sqrt(3) / 2 + 2 * margin;

  const plot = Plot.plot(VM.plotting.plotOptions({
    width,
    height,
    margin,
    grid: false,
    x: {domain: [0, 1], axis: null},
    y: {domain: [0, Math.sqrt(3) / 2], axis: null},
    marks: [
      Plot.geo({ type: "FeatureCollection", features }, {
        fill: d =&gt; d.properties.fillColor,
        stroke: colors.ink,
        strokeWidth: 1
      }),
      Plot.link(mixedEdges, {
        x1: "x1", y1: "y1", x2: "x2", y2: "y2",
        stroke: "color",
        strokeWidth: 3
      }),
      Plot.dot(morphedPoints.morphedPoints, {
        x: "x", y: "y", fill: d =&gt; VM.discreteMath.vertexColor(d.color), r: 4
      })
    ]
  }));

  let svgRoot = plot;
  if (plot.tagName !== 'svg') svgRoot = plot.querySelector('svg');
  if (svgRoot) svgRoot.prepend(makeOrientationDefs(ccwId, cwId, colors.accent2));

  return plot;
}
morpherValid = createTriangleMorpher(N, vertices, VM.discreteMath.spernerColor)

colorMapValid = {
  comparisonRegenerate;
  return morpherValid.buildColorMap();
}

morphedValid = morpherValid.interpolatePoints(t, colorMapValid)
trianglesValid = morpherValid.generateSubTriangles(morphedValid.morphedMap)
plotValid = plotTriangles(trianglesValid, morphedValid, N, chartColors)
morpherInvalid = createTriangleMorpher(N, vertices, simplerAssignColor)

colorMapInvalid = {
  comparisonRegenerate;
  return morpherInvalid.buildColorMap();
}

morphedInvalid = morpherInvalid.interpolatePoints(t, colorMapInvalid)
trianglesInvalid = morpherInvalid.generateSubTriangles(morphedInvalid.morphedMap)
plotInvalid = plotTriangles(trianglesInvalid, morphedInvalid, N, chartColors)
Let \(v^R\), \(v^G\), and \(v^B\) be the vertices of the original triangle, colored red, green, and blue, respectively.
Consider a triangulation \(\Delta\) of the triangle \((v^R, v^G, v^B)\). We’ll use the variable \(\delta\) to refer to the smaller triangles within this triangulation \(\Delta\). Assume each \(\delta\) is oriented counterclockwise, consistent with the orientation of \((v^R, v^G, v^B)\). This orientation will be important when we define signed areas.

Time
We’ll now describe how this triangulation evolves over time.
Let \(t\) be a real number in \([0, 1]\). Let \(v\) be a vertex in the subdivision, and let \(c(v)\) denote the color of \(v\). Define: \[\begin{align*}
v_t = (1 - t) \cdot v + t \cdot v^{c(v)}
\end{align*}\] so that \(v_0 = v\) and \(v_1 = v^{c(v)}\). For each triangle \(\delta = (v^1, v^2, v^3) \in \Delta\), define: \[\begin{align*}
\delta_t = (v^1_t, v^2_t, v^3_t)
\end{align*}\] and let: \[\begin{align*}
\Delta_t = \{ \delta_t : \delta \in \Delta \}.
\end{align*}\] Note that \(\Delta_0 = \Delta\). However, \(\Delta_t\) is simply a collection of triangles — it is not necessarily a triangulation of any shape. In fact, the triangles may overlap, and the union of \(\Delta_t\) may not form a proper region. (The “Time” slider above is exactly this \(t\) — moving it slowly from \(0\) shows you \(\Delta_t\) for small \(t\), which is the regime the theorem below is about.)
Our goal is to understand how \(\Delta_t\) behaves as \(t\) changes.

// VM is the shared utility library, loaded globally via _includes/head-scripts.html (js/**). This page uses VM.numerical.linearRegression, VM.expressions.makeFunction, VM.expressions.makeNumber, VM.plotting.paddedRange, VM.ui.renderTable, VM.ui.applyExampleParams.
VM = window.VM







urlParams = new URLSearchParams(window.location.search)

initialMax = urlParams.get("max") ?? "20"
















traceOptions = ["f(x)", "Secant line", "Secant points", "Secant x-intercepts"]

// Matches the line/marker colors mainPlot uses for each trace, so the
// overlay legend's swatches double as a color key.
// vmTheme is what makes the colors below reactive. The chart's own chrome
// (background, axes, gridlines) repaints on a dark-mode toggle by itself,
// via the relayout patch in plotly-fullscreen-button.js -- but the *trace*
// colors are values this page bakes into the traces it builds, so nothing
// repaints them unless mainPlot re-runs. Depending on vmTheme is what
// re-runs it. See VM.plotting.onThemeChange for why it fires a couple of
// frames after the toggle rather than inline.
vmTheme = Generators.observe(notify =&gt; VM.plotting.onThemeChange(notify))

chartColors = VM.plotting.colors(vmTheme)

traceColors = new Map([
  ["f(x)", chartColors.fn],
  ["Secant line", chartColors.alt],
  ["Secant points", chartColors.alt],
  ["Secant x-intercepts", chartColors.ok]
])






























// examples backs the "Try an example" dropdown near the top controls.
examples = [
  {
    title: "Nearly horizontal secant",
    params: {max: "20", f: "x^3 - 2*x + 2", x0: "0.7", x1: "0.9"}
  },
  {
    title: "Problematic secant pair",
    params: {max: "20", f: "x^3 - 2*x + 2", x0: "0", x1: "1"}
  },
  {
    title: "Sensitive starting pair",
    params: {max: "20", f: "x^3 - 2*x + 2", x0: "-2", x1: "0"}
  },
  {
    title: "Standard superlinear convergence",
    params: {max: "20", f: "x^3 - x - 2", x0: "1", x1: "2"}
  },
  {
    title: "Large jumps from shallow slopes",
    params: {max: "20", f: "atan(x)", x0: "1", x1: "2"}
  },
  {
    title: "Multiple root behavior",
    params: {max: "20", f: "x^3", x0: "-0.5", x1: "0.8"}
  }
]










viewof fText = {
  const params = new URLSearchParams(window.location.search)
  const fTextInput = Inputs.text({label: "Function f(x)", value: params.get("f") ?? "atan(x)", placeholder: "Example: x^3 - x - 2, cos(x) - x"})
  fTextInput.classList.add("ojs-fill")
  fTextInput.dataset.exampleField = "f"
  return fTextInput
}







// Plot commits the current function/x₀/x₁ fields — edits above don't take
// effect until this is clicked, so result/mainPlot don't recompute on
// every keystroke. The step slider overlaid on the plot is unaffected and stays reactive.
viewof plotTrigger = {
  const plotButton = Inputs.button("Plot", {value: 0, reduce: v =&gt; v + 1})
  plotButton.classList.add("ojs-auto")
  return plotButton
}









viewof x0 = {
  const params = new URLSearchParams(window.location.search)
  const x0Input = Inputs.text({label: "Initial guess x₀", value: params.get("x0") ?? "1", placeholder: "Example: 1, pi/4"})
  x0Input.dataset.exampleField = "x0"
  return x0Input
}







viewof x1 = {
  const params = new URLSearchParams(window.location.search)
  const x1Input = Inputs.text({label: "Initial guess x₁", value: params.get("x1") ?? "2", placeholder: "Example: 2, e"})
  x1Input.dataset.exampleField = "x1"
  return x1Input
}







// Always-live (not gated behind Plot) — it bounds the step slider rather
// than feeding result, so there's no reason to wait for a commit. Shares
// this row with the commit-gated fields now that a shorter label leaves
// room; see urlSyncControls below for how it stays in the URL.
viewof maxIterationsInput = {
  const input = Inputs.text({value: initialMax, label: "Max n", placeholder: "Example: 20, 5*4"})
  input.dataset.exampleField = "max"
  return input
}







viewof exampleSelect = {
  const options = [null, ...examples]
  const select = Inputs.select(options, {label: "Try an example", format: e =&gt; e ? e.title : "Pick an example…", value: null})
  select.classList.add("ojs-fill")
  return select
}








// Plain CSS selectors, not direct viewof references -- see
// js/ui/apply-example.js's comment for why.
exampleFieldSelectors = ({f: '[data-example-field="f"]', x0: '[data-example-field="x0"]', x1: '[data-example-field="x1"]', max: '[data-example-field="max"]'})







// Applies the selected example's params to the fields above and clicks
// Plot, in place — no page reload, so no scroll jump either. A plain
// "change" listener attached once to the stable native &lt;select&gt; (rather
// than an OJS cell reactive on exampleSelect's value) — a &lt;select&gt; fires
// both "input" and "change" per selection, and a reactive cell would run
// once per event, with two overlapping calls racing each other.
applyExampleFromSelect = {
  const nativeSelect = (viewof exampleSelect).querySelector("select")
  if (!nativeSelect) return
  nativeSelect.addEventListener("change", () =&gt; {
    const example = (viewof exampleSelect).value
    if (!example) return
    VM.ui.applyExampleParams(exampleFieldSelectors, example.params, viewof plotTrigger)
  })
}








// Pressing Enter in the function/x₀/x₁ fields clicks Plot instead of
// submitting the field's own (invisible) form. Depends only on the stable
// views, so this wiring runs once and is never re-attached.
enterToPlot = {
  for (const view of [viewof fText, viewof x0, viewof x1]) {
    const input = view.querySelector("input")
    if (!input) continue
    input.addEventListener("keydown", (e) =&gt; {
      if (e.key !== "Enter") return
      e.preventDefault()
      viewof plotTrigger.querySelector("button").click()
    })
  }
}







// committed snapshots fText/x0/x1 only when Plot is clicked, and writes them
// back into the URL so the address bar stays a shareable link. It reads
// `viewof fText`/`viewof x0`/`viewof x1` (the stable DOM views) rather than
// `fText`/`x0`/`x1` (the reactive values), so it does NOT rerun on every
// keystroke — only when `plotTrigger` changes. It still runs once on
// initial page load, so the first render uses the URL-provided (or default)
// values with no click.
committed = {
  plotTrigger
  const math = window.math
  const fVal = (viewof fText).value
  const x0Text = (viewof x0).value
  const x1Text = (viewof x1).value
  const x0Val = VM.expressions.makeNumber(math, x0Text)
  const x1Val = VM.expressions.makeNumber(math, x1Text)

  const params = new URLSearchParams(window.location.search)
  params.set("f", fVal)
  params.set("x0", x0Text)
  params.set("x1", x1Text)
  history.replaceState(null, "", `${window.location.pathname}?${params}`)

  return {fText: fVal, x0: x0Val, x1: x1Val}
}







// max is always-live rather than commit-gated, so it gets its own sync cell
// instead of piggybacking on committed above (which only runs when Plot is
// clicked).
urlSyncControls = {
  const params = new URLSearchParams(window.location.search)
  params.set("max", maxIterationsInput)
  history.replaceState(null, "", `${window.location.pathname}?${params}`)
  return true
}







showFCurve = traces.includes("f(x)")







showSecant = traces.includes("Secant line")







showSecantPoints = traces.includes("Secant points")







showIntercepts = traces.includes("Secant x-intercepts")







// result: runs the secant method with the current committed inputs.
//   rows   — array of { i, xPrev, x, fxPrev, fx, xNext, error }, one entry per iteration
//   points — every x visited so far, x_0, x_1, ..., x_N (used for the
//            iterates plot, which needs the initial guesses too)
//   f      — parsed function, reused for curve sampling in setup
result = {
  const math = window.math

  // Parse f(x) from the committed string. makeFunction returns null if the
  // expression is invalid.
  const f = VM.expressions.makeFunction(math, committed.fText)
  const fallback = x =&gt; NaN

  if (!f) return {rows: [], points: [], f: fallback}

  const initialGuess0 = committed.x0
  const initialGuess1 = committed.x1

  if (!Number.isFinite(initialGuess0) || !Number.isFinite(initialGuess1)) return {rows: [], points: [], f}

  const points = [{x: initialGuess0, fx: f(initialGuess0)}, {x: initialGuess1, fx: f(initialGuess1)}]
  const rows = []

  let i = 1
  while (i &lt;= maxIterations) {
    const prev = points[i - 1]
    const curr = points[i]

    // Stop if either point's f-value blew up — the method has diverged.
    if (!Number.isFinite(prev.fx) || !Number.isFinite(curr.fx)) {
      rows.push({i, xPrev: prev.x, x: curr.x, fxPrev: prev.fx, fx: curr.fx, xNext: NaN, error: NaN})
      return {rows, points, f}
    }

    // Stop if either current secant point is already an exact root.
    if (prev.fx === 0) {
      rows.push({i, xPrev: prev.x, x: curr.x, fxPrev: prev.fx, fx: curr.fx, xNext: prev.x, error: 0})
      return {rows, points, f}
    }

    if (curr.fx === 0) {
      rows.push({i, xPrev: prev.x, x: curr.x, fxPrev: prev.fx, fx: curr.fx, xNext: curr.x, error: 0})
      return {rows, points, f}
    }

    // Stop if the secant is nearly flat — dividing by the difference would be unstable.
    if (Math.abs(curr.fx - prev.fx) &lt; 1e-14) {
      rows.push({i, xPrev: prev.x, x: curr.x, fxPrev: prev.fx, fx: curr.fx, xNext: NaN, error: NaN})
      return {rows, points, f}
    }

    // Secant update: x-intercept of the line through (x_{n-1}, f(x_{n-1})) and (x_n, f(x_n))
    const xNext = curr.x - curr.fx * (curr.x - prev.x) / (curr.fx - prev.fx)
    const error = Math.abs(xNext - curr.x)
    rows.push({i, xPrev: prev.x, x: curr.x, fxPrev: prev.fx, fx: curr.fx, xNext, error})

    points.push({x: xNext, fx: f(xNext)})
    i++
  }
  return {rows, points, f}
}







// setup computes the data shared by all three plots below: which rows are
// visible at the current step, and the axis ranges / curve samples for the
// main chart.
setup = {
  const visibleRows = result.rows.slice(0, Math.min(Number(stepControl), result.rows.length) + 1)

  // Axis ranges are computed from ALL rows, not just visibleRows,
  // so the axes stay fixed as the user steps through iterations.
  const xValues = [committed.x0, committed.x1]
  for (const row of result.rows) xValues.push(row.x, row.xNext)
  const xRange = VM.plotting.paddedRange(xValues, {emptyRange: [-3, 3], relativePadding: 0.25, minPadding: 0.5})

  // A wider domain (double the padding of xRange) so the curve is already
  // sampled beyond the initial view — panning/zooming out reveals more of
  // the curve instead of blank canvas. The initial view stays xRange.
  const xBuffer = VM.plotting.paddedRange(xValues, {emptyRange: [-6, 6], relativePadding: 0.5, minPadding: 1.0})

  // Sample f across the buffer range for the smooth curve trace.
  const sampleCount = 700
  const sampleXs = Array.from({length: sampleCount}, (_, i) =&gt; xBuffer.lo + (xBuffer.hi - xBuffer.lo) * i / (sampleCount - 1))
  const sampleYs = []
  for (const x of sampleXs) {
    const y = result.f(x)
    if (Number.isFinite(y) && Math.abs(y) &lt; 1e8) {
      sampleYs.push(y)
    } else {
      sampleYs.push(null)
    }
  }

  // Collect y values for the y-axis range, including secant line endpoints.
  // Only samples within the initial view (xRange) count, so yRange — and
  // the initial view — stay unaffected by the wider sampling.
  // Cap at 1e8 so a near-vertical secant doesn't blow up the axis range.
  const yValues = [0]
  for (let i = 0; i &lt; sampleXs.length; i++) {
    const x = sampleXs[i]
    if (x &gt;= xRange.lo && x &lt;= xRange.hi && sampleYs[i] !== null) yValues.push(sampleYs[i])
  }
  for (const row of result.rows) {
    if (Number.isFinite(row.fx) && Math.abs(row.fx) &lt;= 1e8) yValues.push(row.fx)
    if (Number.isFinite(row.fxPrev) && Math.abs(row.fxPrev) &lt;= 1e8) yValues.push(row.fxPrev)
    if (Number.isFinite(row.xPrev) && Number.isFinite(row.fxPrev) && Number.isFinite(row.x) && Number.isFinite(row.fx) && Number.isFinite(row.xNext) && row.x !== row.xPrev) {
      const slope = (row.fx - row.fxPrev) / (row.x - row.xPrev)
      const tlo = Math.max(xRange.lo, Math.min(row.xPrev, row.x, row.xNext) - 0.75)
      const thi = Math.min(xRange.hi, Math.max(row.xPrev, row.x, row.xNext) + 0.75)
      for (const v of [row.fx + slope * (tlo - row.x), row.fx + slope * (thi - row.x)]) {
        if (Number.isFinite(v) && Math.abs(v) &lt;= 1e8) yValues.push(v)
      }
    }
  }
  const yRange = VM.plotting.paddedRange(yValues, {emptyRange: [-1, 1], relativePadding: 0.25, minPadding: 0.5})

  return {visibleRows, xRange, xBuffer, yRange, sampleXs, sampleYs}
}







// mainPlot draws f(x), the secant lines, the secant points, and the
// secant x-intercepts.
//
// _plotDiv is kept in a closure so Plotly reuses the same DOM node across
// reactive updates — this preserves zoom and pan when the step changes.
mainPlot = {
  const Plotly = window.Plotly
  let _plotDiv = null

  return ({visibleRows, xRange, xBuffer, yRange, sampleXs, sampleYs}, showFCurve, showSecant, showSecantPoints, showIntercepts) =&gt; {
    const data = []

    if (showFCurve) {
      // The function curve
      data.push({x: sampleXs, y: sampleYs, type: "scatter", mode: "lines", name: "f(x)", showlegend: false, line: {color: chartColors.fn, width: 3}})
    }

    // Every point used so far: x_0 (from the first visible row's xPrev)
    // followed by x_i for each visible row.
    const secantPoints = []
    if (visibleRows.length &gt; 0) {
      const first = visibleRows[0]
      if (Number.isFinite(first.xPrev) && Number.isFinite(first.fxPrev)) {
        secantPoints.push({i: first.i - 1, x: first.xPrev, fx: first.fxPrev})
      }
    }
    for (const r of visibleRows) {
      if (Number.isFinite(r.x) && Number.isFinite(r.fx)) secantPoints.push({i: r.i, x: r.x, fx: r.fx})
    }

    // Dotted vertical lines from the x-axis up to each secant point
    if (showSecantPoints) {
      for (const p of secantPoints) {
        data.push({x: [p.x, p.x], y: [0, p.fx], type: "scatter", mode: "lines", showlegend: false, hoverinfo: "skip", line: {color: chartColors.muted, width: 1.5, dash: "dot"}})
      }
    }

    // Secant lines: previous ones faded, current one solid. Each spans
    // both secant points and the x-intercept (plus a margin), so the
    // intercept marker is always on the drawn segment.
    const validSecantRows = []
    for (const r of visibleRows) {
      if (Number.isFinite(r.xPrev) && Number.isFinite(r.fxPrev) && Number.isFinite(r.x) && Number.isFinite(r.fx) && Number.isFinite(r.xNext)) {
        validSecantRows.push(r)
      }
    }
    const prevSecants = validSecantRows.slice(0, -1)
    let currentSecant = null
    if (validSecantRows.length &gt; 0) currentSecant = validSecantRows[validSecantRows.length - 1]

    if (showSecant) {
      for (const row of prevSecants) {
        const slope = (row.fx - row.fxPrev) / (row.x - row.xPrev)
        const tlo = Math.max(xRange.lo, Math.min(row.xPrev, row.x, row.xNext) - 0.75)
        const thi = Math.min(xRange.hi, Math.max(row.xPrev, row.x, row.xNext) + 0.75)
        data.push({
          x: [tlo, thi], y: [row.fx + slope * (tlo - row.x), row.fx + slope * (thi - row.x)],
          type: "scatter", mode: "lines", showlegend: false, hoverinfo: "skip",
          line: {color: "rgba(220, 38, 38, 0.18)", width: 1.5}
        })
      }
      if (currentSecant) {
        const row = currentSecant
        const slope = (row.fx - row.fxPrev) / (row.x - row.xPrev)
        const tlo = Math.max(xRange.lo, Math.min(row.xPrev, row.x, row.xNext) - 0.75)
        const thi = Math.min(xRange.hi, Math.max(row.xPrev, row.x, row.xNext) + 0.75)
        data.push({
          x: [tlo, thi], y: [row.fx + slope * (tlo - row.x), row.fx + slope * (thi - row.x)],
          type: "scatter", mode: "lines", name: "Secant line", showlegend: false,
          line: {color: chartColors.alt, width: 2.5}
        })
      }
    }

    // Red markers at each (x_i, f(x_i)) secant point
    if (showSecantPoints && secantPoints.length &gt; 0) {
      const xs = [], ys = [], labels = []
      for (const p of secantPoints) {
        xs.push(p.x)
        ys.push(p.fx)
        labels.push(`x${VM.plotting.subscript(p.i)}`)
      }
      data.push({
        x: xs, y: ys,
        type: "scatter", mode: "markers+text", name: "Secant points",
        text: labels, textposition: "top center", showlegend: false,
        marker: {color: chartColors.alt, size: 10, symbol: "circle", line: {color: chartColors.halo, width: 1}}
      })
    }

    // Green markers at each secant x-intercept (x_{i+1})
    const intercepts = []
    for (const r of visibleRows) {
      if (Number.isFinite(r.xNext)) intercepts.push({i: r.i + 1, x: r.xNext})
    }
    if (showIntercepts && intercepts.length &gt; 0) {
      const xs = [], ys = [], labels = []
      for (const r of intercepts) {
        xs.push(r.x)
        ys.push(0)
        labels.push(`x${VM.plotting.subscript(r.i)}`)
      }
      data.push({
        x: xs, y: ys,
        type: "scatter", mode: "markers+text", name: "Secant x-intercepts",
        text: labels, textposition: "bottom center", showlegend: false,
        marker: {color: chartColors.ok, size: 10, symbol: "circle", line: {color: chartColors.halo, width: 1}}
      })
    }

    const layout = {
      xaxis: {title: "x", range: [xRange.lo, xRange.hi], zeroline: true},
      yaxis: {title: "f(x)", range: [yRange.lo, yRange.hi], zeroline: true},
      hovermode: "closest",
      uirevision: "static",  // keeps zoom/pan state across reactive updates
      autosize: true
    }
    const config = VM.plotting.config()

    // First render: create the div. Later renders: update in place (preserves zoom).
    if (!_plotDiv) {
      _plotDiv = document.createElement("div")
      _plotDiv.className = "plotly-box-large"
      Plotly.newPlot(_plotDiv, data, layout, config)
      // newPlot fires before the div is in the DOM, so Plotly measures 0 width.
      // A ResizeObserver catches the real size once it's inserted and laid out,
      // and keeps correcting it on any later layout/viewport change.
      VM.plotting.autoResize(_plotDiv)
    } else {
      Plotly.react(_plotDiv, data, layout, config)
    }
    return _plotDiv
  }
}







