  let circles = ""
  for (let slot = 0; slot &lt; count; slot++) {
    const person = people[order[slot]]
    const cx = (Math.floor(slot / rows) + 0.5) * pitch
    const cy = ((slot % rows) + 0.5) * pitch
    let color = config.colors.healthy
    if (person.infected) color = config.colors.infected
    // A literal newline inside a quoted attribute is kept as-is by the HTML
    // parser; the tooltip's white-space: pre-line turns it into a line break.
    const tip = `data-tip="${personTooltip(person, rounds)}"`
    if (rounds &gt; 0 && person.clearedRound !== null && person.clearedRound &lt;= rounds) {
      const opacity = fadeOpacity(rounds, person.clearedRound, person.infected)
      circles += `&lt;circle cx="${cx.toFixed(2)}" cy="${cy.toFixed(2)}" r="${(radius - ringWidth / 2).toFixed(2)}" fill="none" stroke="${color}" stroke-width="${ringWidth.toFixed(2)}" opacity="${opacity.toFixed(3)}" ${tip}/&gt;`
    } else {
      circles += `&lt;circle cx="${cx.toFixed(2)}" cy="${cy.toFixed(2)}" r="${radius.toFixed(2)}" fill="${color}" ${tip}/&gt;`
    }
  }

  // Returned inside a &lt;div&gt;, not as the bare &lt;svg&gt;: Quarto's OJS output
  // inspects a bare SVGSVGElement as a value ("SVGSVGElement {}") instead
  // of inserting it, whereas an HTMLElement is inserted as a node.
  const holder = document.createElement("div")
  holder.className = "ppv-grid"
  holder.innerHTML = `&lt;svg viewBox="0 0 ${width} ${height.toFixed(2)}" xmlns="http://www.w3.org/2000/svg" role="img"&gt;${circles}&lt;/svg&gt;`
  const svg = holder.firstElementChild
  // A hollow ring has fill="none", and by default only its painted stroke
  // is hoverable -- the hole in the middle would show no tooltip. "all"
  // (inherited by every circle) makes the whole disc a target either way.
  svg.style.pointerEvents = "all"
  attachTooltip(svg)
  return holder
}

// swatch: the inline legend mark used in the explanation panels -- a solid
// dot, or a hollow ring at the given fade -- matching how the grids draw
// people.
function swatch(color, filled, opacity = 1) {
  let cls = "ppv-swatch"
  if (filled) cls += " filled"
  return html`&lt;i class="${cls}" style="color: ${color}; opacity: ${opacity}"&gt;&lt;/i&gt;`
}

// legendPanel: the panel under the grid -- a title, then one row per kind of
// dot in the picture (`rows` is [{color, filled, opacity, count, label}]),
// and an optional closing note (PPV and so on). Two rows may share a
// swatch: the picture draws a person missed by the first test and one
// missed by the second identically, and the legend lists them apart
// rather than summing them into one number the picture can't show.
function legendPanel(title, rows, note) {
  const cells = []
  for (const row of rows) {
    cells.push(swatch(row.color, row.filled, row.opacity ?? 1))
    cells.push(html`&lt;span class="ppv-legend-count"&gt;${row.count}&lt;/span&gt;`)
    cells.push(html`&lt;span&gt;${row.label}&lt;/span&gt;`)
  }
  let noteNode = ""
  if (note) noteNode = html`&lt;div class="ppv-legend-note"&gt;${note}&lt;/div&gt;`
  return html`&lt;div class="ojs-panel"&gt;&lt;strong&gt;${title}&lt;/strong&gt;&lt;div class="ppv-legend-rows"&gt;${cells}&lt;/div&gt;${noteNode}&lt;/div&gt;`
}
Even a highly accurate test gives a weak positive result when the condition is rare: the healthy population is so much larger that a small false-positive rate among them outnumbers the true positives among the few who are sick. That is what the solid dots show: a handful of red in a crowd of dark.
Retesting works because each repeat test starts from a population whose prevalence is the previous round’s PPV, so the same sensitivity and specificity give a much sharper result. Bayes’ rule is this update, with the denominator split into the two ways a test can come back positive:
\[
\begin{aligned}
P(\text{condition} \mid \text{positive})
&= \frac{P(\text{positive} \mid \text{condition})\, P(\text{condition})}{P(\text{positive})} \\[0.6em]
&= \frac{P(\text{positive} \mid \text{condition})\, P(\text{condition})}
        {P(\text{positive} \mid \text{condition})\, P(\text{condition}) + P(\text{positive} \mid \text{no condition})\, P(\text{no condition})} \\[0.6em]
&= \frac{\text{true positives}}{\text{true positives} + \text{false positives}}.
\end{aligned}
\]

