Consider a triangulation of a triangle. (Below, we show a regular triangulation of an equilateral triangle, but the theorem applies to any triangulation of a triangle.) We color the vertices of the triangle with three colors—say, red, green, and blue—with the following conditions:
Conditions 1 and 2 are often referred to as the Sperner condition.
In fact, you always have an odd number of such triangles.
// VM is the shared utility library, loaded globally via _includes/head-scripts.html (js/**). This page uses VM.discreteMath.barycentricTriples, VM.discreteMath.subTriangleTriples, VM.discreteMath.spernerColor, VM.discreteMath.triangulationEdges, VM.discreteMath.pairColor, VM.discreteMath.triangleFillColor, VM.discreteMath.vertexColor.
VM = window.VM
vmTheme = Generators.observe(notify =&gt; VM.plotting.onThemeChange(notify))
chartColors = VM.plotting.colors(vmTheme)
vertices = [
  {x: 1, y: 0},
  {x: 0.5, y: Math.sqrt(3) / 2},
  {x: 0, y: 0},
]
class ColoredPoint {
  constructor(triple, vertices, N) {
    this.barycentricTriple = triple;
    const [A, B, C] = vertices;

    this.x = (triple[0] * A.x + triple[1] * B.x + triple[2] * C.x) / N;
    this.y = (triple[0] * A.y + triple[1] * B.y + triple[2] * C.y) / N;

    const [a, b, c] = triple;
    this.color = VM.discreteMath.spernerColor(a, b, c);
  }

  getCoords() {
    return { x: this.x, y: this.y };
  }

  getColor() {
    return this.color;
  }
}
colored = {
  regenerate;
  const points = [];
  for (const triple of VM.discreteMath.barycentricTriples(N)) {
    points.push(new ColoredPoint(triple, vertices, N));
  }

  const byKey = new Map();
  for (const p of points) {
    byKey.set(p.barycentricTriple.join(','), p);
  }

  return { points, byKey };
}
subTriangles = {
  const triangles = [];
  for (const coordinates of VM.discreteMath.subTriangleTriples(N)) {
    const vertex_colors = new Set();
    for (const coord of coordinates) {
      vertex_colors.add(colored.byKey.get(coord.join(',')).getColor());
    }
    triangles.push({ coordinates, vertex_colors });
  }
  return triangles;
}
// Edges between differently-colored vertices, in the shared amber/teal/
// purple pair palette (VM.discreteMath.pairColor). Same-color edges are
// skipped entirely to avoid clutter. chartColors is referenced so the
// stored colors are recomputed on a theme toggle.
mixedEdges = {
  chartColors;
  const edges = [];
  for (const { a, b } of VM.discreteMath.triangulationEdges(N)) {
    const pa = colored.byKey.get(a.join(','));
    const pb = colored.byKey.get(b.join(','));
    const color = VM.discreteMath.pairColor(pa.getColor(), pb.getColor());
    if (!color) continue;
    const ca = pa.getCoords();
    const cb = pb.getCoords();
    edges.push({ x1: ca.x, y1: ca.y, x2: cb.x, y2: cb.y, color });
  }
  return edges;
}
numRGBTriangles = {
  let count = 0;
  for (const triangle of subTriangles) {
    if (triangle.vertex_colors.size === 3) count++;
  }
  return count;
}
